args.sql:
SELECT COUNT(*) FROM (
    SELECT sp.techsigprob * (1 - sp.natsrcprob) * sp.sigunique * (0.5 + sp.anomscore / 10) AS tols_val
    FROM signals s
    JOIN signalprobabilities sp ON s.signalregistry = sp.signalref
) t WHERE tols_val >= 0.75;

